groupRoutes.put("/:groupId/owner/:memberId", async (c5) => {
  const user = c5.get("user"), groupId = c5.req.param("groupId"), nextOwner = c5.req.param("memberId");
  const group4 = await groupConversation(groupId);
  if (!group4 || group4.owner_id !== user.id) return jsonError(c5, 403, "GROUP_OWNER_REQUIRED", "Only the current owner can transfer ownership.");
  const member2 = await roleFor(nextOwner, groupId);
  if (!member2) return jsonError(c5, 404, "GROUP_MEMBER_NOT_FOUND", "The new owner must already be a group member.");
  await getDb().transaction([
    getDb()`UPDATE group_members SET role='admin' WHERE group_id=${groupId} AND user_id=${user.id} AND role='owner'`,
    getDb()`UPDATE group_members SET role='owner' WHERE group_id=${groupId} AND user_id=${nextOwner} AND left_at IS NULL`,
    getDb()`UPDATE haiku_groups SET owner_id=${nextOwner},updated_at=now() WHERE id=${groupId}`
  ]);
  return c5.json({ status: "ownership_transferred", ownerId: nextOwner });
});
