// src/middleware/admin.ts
var requireAdmin = createMiddleware(async (c5, next) => {
  const user = c5.get("user");
  const rows = await getDb()`SELECT r.role_name, r.permissions FROM admin_members m
    JOIN admin_roles r ON r.role_name=m.role_name
    WHERE m.user_id=${user.id} AND m.revoked_at IS NULL LIMIT 1`;
  if (!rows.length) return jsonError(c5, 403, "ADMIN_REQUIRED", "Administrator access is required.");
  const row = rows[0];
  c5.set("admin", { role: row.role_name, permissions: row.permissions || {} });
  await next();
});
function hasAdminPermission(c5, permission) {
  const admin = c5.get("admin");
  return admin.role === "owner" || admin.permissions[permission] === true;
}

